'use strict';
const CATALOG={chat:'聊天',activity:'动态',health:'健康',conversations:'全部对话',search:'搜索',history:'按日期查看',work:'开始一件工作',projects:'项目',resources:'对话中的内容',task:'执行详情',goals:'目标与提醒','goal-detail':'目标详情',reminders:'手机提醒',schedules:'定时任务',library:'成果库','library-detail':'成果预览',memory:'记忆','memory-detail':'记忆详情','memory-cleanup':'遗忘进度','health-detail':'健康趋势','health-settings':'健康数据',settings:'设置',general:'常规',appearance:'外观',account:'账号与安全','change-email':'换绑邮箱','change-password':'修改密码',devices:'设备',models:'模型服务','model-edit':'编辑模型服务',usage:'用量',approvals:'审批',archived:'已归档',system:'系统状态',about:'关于',diagnostics:'运行记录',legal:'隐私与条款',login:'登录',register:'注册',recovery:'找回密码',verify:'验证邮箱',pairing:'添加电脑','pair-confirm':'确认配对'};
const AUTH_ROUTES=['login','register','recovery','verify','pairing','pair-confirm'];
const search=(placeholder,scope)=>`<label class="search-field">${icon('search')}<input type="search" aria-label="${placeholder}" placeholder="${placeholder}" data-search="${scope}"></label>`;
const offlineNote=()=>S.state==='offline'?`<div class="notice">电脑暂时连不上，先看上次保存的内容。${button('查看连接','data-go="devices"')}</div>`:'';
const MEMORIES={preference:{title:'周末喜欢留白',sources:['这周末想少安排一点','留出一个不赶时间的上午'],correction:'不是所有周末，只是最近想安排得松一些。'},fact:{title:'最近在读的书',sources:['最近开始读一本关于城市散步的书'],correction:'那本书已经读完了，现在在整理笔记。'},review:{title:'周六早晨的安排',sources:['这周六早晨还不能确定是否有空'],correction:'已经确定了，周六早晨有空。'}};
function memorySources(){if(S.forgottenIDs.has(S.memoryID))return note('所列来源已清理。');return MEMORIES[S.memoryID].sources.map(text=>row('quote','「'+text+'」','打开对应原话',`data-source="${S.memoryID}"`)).join('');}
function metricSeries(){const bases={sleep:456,recovery:82,load:45,stress:32,energy:76,hrv:48,heart:58,respiratory:14,temperature:.1,steps:6240};const base=bases[S.metric]??50,scale=S.metric==='temperature'?.08:base*.14;return Array.from({length:S.metricDays},(_,i)=>{const date=new Date(2026,9,28-S.metricDays+i);return {date:`${date.getMonth()+1} 月 ${date.getDate()} 日`,short:`${date.getMonth()+1}/${date.getDate()}`,value:base+Math.sin(i*1.4)*scale};});}
function formatMetric(value){return S.metric==='sleep'?`${Math.floor(value/60)} 小时 ${Math.round(value%60)} 分`:S.metric==='steps'?`${Math.round(value).toLocaleString('zh-CN')} 步`:S.metric==='temperature'?`${value.toFixed(1)} °C`:S.metric==='heart'?`${Math.round(value)} 次 / 分`:S.metric==='respiratory'?`${Math.round(value)} 次 / 分`:S.metric==='hrv'?`${Math.round(value)} 毫秒`:`${Math.round(value)} 分`;}
function metricChart(){const points=metricSeries(),values=points.map(p=>p.value),low=Math.min(...values),high=Math.max(...values);const coords=values.map((v,i)=>`${8+i/(values.length-1)*324},${140-(v-low)/(high-low||1)*100}`);return `<button class="chart" data-action="chart-point" aria-label="查看${metricData[S.metric][0]}的某一天测量" style="width:100%"><svg viewBox="0 0 340 180" role="img" aria-label="${S.metricDays} 天合成趋势"><path class="chart-area" d="M0 50H340V135H0Z"/><path class="grid" d="M0 30H340M0 90H340M0 150H340"/><polyline class="trend" points="${coords.join(' ')}"/></svg><div class="chart-labels"><span>${points[0].short}</span><span>${points[Math.floor(points.length/2)].short}</span><span>${points.at(-1).short}</span></div></button>`;}
const metricData={sleep:['睡眠时长','7 小时 36 分','比前一晚多 28 分钟','moon'],recovery:['恢复','82','和平时相比，恢复不错','health'],load:['活动负荷','适中','根据已有活动记录','pulse'],stress:['压力','平稳','最近测量 08:45','pulse'],energy:['电能','76','查看夜间恢复与白天消耗','battery'],'fitness-age':['体能年龄','暂无估计','还缺少最大摄氧量','health'],hrv:['心率变异性','48 毫秒','个人常见范围 36–58','pulse'],heart:['静息心率','58 次 / 分','个人常见范围 55–64','health'],respiratory:['呼吸频率','14 次 / 分','个人常见范围 12–17','lungs'],oxygen:['血氧','暂无测量','不以零代替缺少的测量','oxygen'],temperature:['手腕温度','+0.1 °C','相对个人基线','temperature'],steps:['步数','6,240 步','今日活动','pulse']};
const PAGES={
chat:()=>S.state==='error'?`<div class="user-message">帮我把周末安排得松一点。</div><div class="chat-error"><p class="inline-error">这次没回复，可以重试。</p>${button('重试回复','data-action="retry-reply"','outline')}</div>`:`${S.state==='offline'?'<div class="notice">电脑离线，手机用账户云模型继续聊。'+button('交给电脑，上线后做','data-sheet="offline-work"')+'</div>':''}<div class="day-label">今天 · 09:28</div>${S.forgotten?note('这条来源已随记忆清理。'):'<div class="user-message" data-memory-source="preference">周末想去公园走走，帮我留出一个不赶时间的上午。</div>'}<button class="process" data-action="process" aria-expanded="false">${icon('allow')}已整理好安排 · 2 个步骤${icon('chevron')}</button><div class="process-detail" hidden>读懂你的安排<br>整理一个留有余地的上午<br>${button('查看过程与来源','data-go="resources"')}</div><article class="answer"><p class="lead">那就把上午留给散步。</p><p>不用排满，也不必赶早。留两个时间点，其他的随心就好。</p><ol><li><strong>09:30 左右出发。</strong><br>带上水，穿双舒服的鞋。</li><li><strong>先沿湖走一小圈。</strong><br>喜欢哪里，就在哪里多坐一会儿。</li><li><strong>11:00 前后，自由返程。</strong><br>还想待着就再待一会儿。</li></ol><p>我把这份安排留成了小清单，出门前看一眼就够了。</p></article><div class="group">${linkRow('file','周末散步清单','library-detail','文档 · 刚刚生成')}</div><div class="answer-actions">${ib('copy','复制回复','data-action="copy"')}${ib('sync','重新生成','data-action="stream"')}${ib('more','对话操作','data-sheet="conversation"')}<small>账户云模型</small></div><div class="suggestions"><button data-fill="如果下雨呢？">如果下雨呢？</button><button data-fill="明天九点提醒我带水">设一个出门提醒</button></div>`,
activity:()=>`${title('动态','该你处理的，先放在前面。')}${offlineNote()}${segment(['全部','未读','待处理'],'动态范围')}<div class="row-between"><h3 class="section-title">今天</h3><button class="inline-link" data-action="mark-read">全部已读</button></div><button class="activity-row unread" data-sheet="approval"><span class="activity-icon danger">${icon('approval')}</span><span><h3>整理书房清单，需要你点头</h3><p>将替换项目里的同名文件。确认影响后，再继续。</p><small>待批准 · 4 分钟前</small></span></button><button class="activity-row unread" data-go="library-detail"><span class="activity-icon">${icon('outputs')}</span><span><h3>散步清单已经整理好了</h3><p>来自「周末的散步计划」，可以直接打开。</p><small>已完成 · 12 分钟前</small></span></button><button class="activity-row" data-sheet="weekly"><span class="activity-icon">${icon('book')}</span><span><h3>这一周，留下了什么</h3><p>完成了两件小事，也给自己留了一个轻松的上午。</p><small>每周回顾 · 昨天</small></span></button><button class="activity-row" data-go="memory"><span class="activity-icon">${icon('bookmark')}</span><span><h3>记忆有一处需要你核对</h3><p>对「周末安排」的理解有变化，看看是否准确。</p><small>记忆整理 · 昨天</small></span></button>${button('查看更多动态','data-feedback="示例动态已全部显示"','full outline')}`,
health:()=>`${title('健康','10 月 27 日，星期二')}${offlineNote()}<div class="row-between"><span class="chip">${icon('sync')}08:45 更新 · 示例</span><button class="inline-link" data-go="health-settings">数据与权限</button></div><button class="health-summary" data-metric="recovery" style="width:100%;text-align:left"><span class="health-score">82</span><span><h3>恢复不错</h3><p>和平时相比，身体准备好了。</p></span>${icon('right')}</button><div class="health-mini"><button data-metric="stress">压力<strong>平稳</strong></button><button data-metric="energy">电能<strong>76 <small>/ 100</small></strong></button><button data-metric="load">活动负荷<strong>适中</strong></button></div><button class="health-sleep" data-metric="sleep"><div class="row-between"><h3>${icon('moon')}昨晚睡眠</h3>${icon('right')}</div><strong>7 <small>小时</small> 36 <small>分</small></strong><span class="caption">23:14 入睡 · 07:02 起床</span><div class="sleep-track" aria-label="睡眠分期合成示意">${'<span></span>'.repeat(24)}</div><div class="row-between caption"><span>深睡 1 小时 24 分</span><span>比前一晚多 28 分钟</span></div></button><h3 class="section-title">身体指标</h3>${[['heart','health','静息心率','58','次 / 分','var(--health-resting-heart-rate)'],['hrv','pulse','心率变异性','48','毫秒','var(--health-hrv)'],['oxygen','oxygen','血氧','—','暂无测量','var(--health-oxygen)'],['respiratory','lungs','呼吸频率','14','次 / 分','var(--health-respiratory)'],['temperature','temperature','手腕温度','+0.1','°C · 相对基线','var(--health-temperature)']].map(([key,i,label,v,u,color])=>`<button class="health-measure" data-metric="${key}"><span style="color:${color};flex:0">${icon(i)}</span><span>${label}</span><strong>${v}<small>${u}</small></strong></button>`).join('')}<h3 class="section-title">今天的活动</h3><div class="group">${row('pulse','6,240 步','活动能量 286 千卡 · 运动 32 分钟','data-metric="steps"')}${row('health','体能年龄','还缺少最大摄氧量','data-metric="fitness-age"')}</div><h3 class="section-title">这个月的运动</h3><div class="calendar" aria-label="十月运动记录合成示例">${Array.from({length:31},(_,i)=>`<span class="${i%3===0?'marked':''}">${i+1}</span>`).join('')}</div>${section('今日解读',row('chat','看看这些变化意味着什么','由你决定是否启用 AI 分析','data-sheet="health-analysis"'))}${note('分数与文字均为合成示例。缺少的测量留空，趋势估计不替代医疗判断。')}`,
'health-detail':()=>{const [name,value,sub]=metricData[S.metric];return `${title(name,sub)}<div class="metric-number">${value}</div>${note('最近更新 08:45 · 合成示例')}${segment(['7 天','14 天','30 天','60 天'],'趋势范围',[7,14,30,60].indexOf(S.metricDays))}<h3 id="chart-range" class="caption">${S.metricDays} 天内的每日测量</h3>${['oxygen','fitness-age'].includes(S.metric)?`<div class="empty">${icon('health')}<h3>这段时间还没有测量</h3><p>先查看已经有的数据，不填入估算值。</p>${button('检查读取项目','data-go="health-settings"','outline')}</div>`:`<div class="chart-container">${metricChart()}</div><p id="chart-selection" class="caption">点图表查看某一天</p>${note('浅色区间是个人常见范围；原生版支持按住图表查看每日值。')}${section('一起看看',toggle('叠加深夜使用时间','只展示变化关联，不推断因果',false))}`}<h3 class="section-title">为什么是这个结果</h3><p class="secondary" style="font-size:var(--f-14)">${S.metric==='sleep'?'昨晚比前一晚多睡了 28 分钟。深睡 1 小时 24 分，快速眼动 1 小时 42 分。':S.metric==='energy'?'夜间恢复 34，白天消耗 18；缺少测量的时段不补值。':S.metric==='stress'?'根据心率变异性和心率估计，再与你的个人基线比较。':sub}</p>${note('基线已有 14 天测量；详细依据、缺失项与来源在这里展开。')}${button('让 AI 分析这一项','data-sheet="health-analysis"','full outline')}${button('接着问它','data-fill="帮我看看最近的'+name+'变化"','full')}`;},
'health-settings':()=>`${title('健康数据','由你决定读取什么、用在哪里。')}${section('读取与同步',toggle('读取健康数据','只向本人电脑发送每日与小时摘要',!S.healthDeleted)+row('health','选择读取项目','步数、睡眠、心率、运动等','data-sheet="health-permission"')+row('sync','更新摘要','上次更新 08:45','data-feedback="已更新合成摘要"'))}${section('解读',toggle('今日解读与 AI 分析','仅启用后才请求分析',false)+toggle('每日摘要可用于云模型','设备端指标与小时摘要仍仅供本地使用',S.healthCloud,'health-cloud'))}${section('查看数据',row('list','每日摘要','查看汇总值、基线与同步状态','data-sheet="health-summary"')+row('clock','自评频率','自评询问尚未开放','data-feedback="当前仅保留设置，尚未开放自评询问"','每周'))}${note('系统不公开读取权限状态。没有数据也可能是未获授权，请在「健康」App 的头像 → App → WeftMate 检查。')}${button('删除摘要并停止读取','data-sheet="health-delete"','full outline danger')}${note('删除摘要不删除「健康」中的原始记录。测试版的健康能力取决于签名与授权，原型不请求权限。')}`,
conversations:()=>`${title('全部对话','对话和工作，各自接着上次。')}${search('搜索对话','conversations')}${segment(['全部','对话','工作'],'对话模式')}<div class="group">${[['周末的散步计划','对话','今天 09:28'],['把书房整理一下','工作','待批准 · 示例电脑'],['读书时记下的想法','对话','昨天'],['下周的三件小事','工作','昨天 · 已完成']].map(([n,k,time])=>`<div class="list-row search-result" data-chat-kind="${k}"><button class="row-copy" data-conversation="${n}" style="text-align:left"><strong>${n}</strong><small>${time}</small></button>${ib('more',n+'的操作','data-sheet="conversation"')}</div>`).join('')}</div><p class="search-empty note" hidden>没有找到这段对话，换个关键词试试。</p>${section('分组',row('folder','生活安排','3 段对话','data-sheet="group"')+row('plus','新建分组','','data-sheet="group"'))}${button('新建对话','data-sheet="new-chat"','full primary')}`,
search:()=>`${title('搜索','从对话、记忆和成果里找。')}${search('搜索，例如「散步」','all')}<h3 class="section-title">最近找到</h3><div class="search-result">${row('chat','周末的散步计划','对话 · 今天','data-conversation="周末的散步计划"')}</div><div class="search-result">${linkRow('file','周末散步清单','library-detail','成果 · 今天')}</div><div class="search-result">${S.forgotten?'':row('bookmark','周末喜欢留出空白时间','记忆 · 来自 2 段对话','data-memory="preference"')}</div><p class="search-empty note" hidden>没有匹配的内容。可以换个词，或按日期查找。</p>${button('按日期查看对话','data-sheet="date"','full outline')}`,
history:()=>`${title('10 月 26 日','连续主对话 · 已定位到这一天')}${button('选择其他日期','data-sheet="date"','full outline')}<div class="day-label" style="margin-top:var(--s-24)">昨天 · 20:15</div>${S.forgottenIDs.has(S.sourceMemory)?note('这条来源已随记忆清理。'):`<div class="user-message" data-memory-source="${S.sourceMemory}">${MEMORIES[S.sourceMemory].sources[0]}</div>`}<article class="answer"><p>好，先留出一个完全不用赶路的上午。等你有想法了，我们再接着安排。</p></article>${section('这一天留下的内容',(S.forgotten?note('对应记忆已遗忘。'):row('bookmark','周末喜欢留白','查看来源与理解','data-memory="preference"')))}${button('查看更早记录','data-feedback="原型已定位到更早一天的示例记录"','full outline')}${button('回到最新对话','data-tab="chat"','full')}`,
work:()=>`${title('开始一件工作','先选好电脑和项目，再交代事情。')}${S.state==='offline'?'<div class="notice">电脑离线，现在可以先暂存任务。</div>':''}${section('这次在哪里做',row('desktop','示例电脑','已连接 · 仅为原型状态','data-sheet="computer"')+row('folder','周末计划','项目 · 允许读写','data-sheet="project"'))}${field('想做什么','例如，把这份安排整理成清单')}<div class="notice">开始工作后，这段对话保持工作模式；想纯聊天可以另开一段。</div>${button('开始工作','data-action="start-work"','full primary')}${button('先继续聊天','data-tab="chat"','full')}`,
projects:()=>`${title('项目','每个工作都归到明确的地方。')}${offlineNote()}<div class="group">${row('folder','周末计划','示例电脑 · 允许读写','data-go="work"')}${row('folder','阅读资料','示例电脑 · 只读','data-go="work"')}${row('plus','添加项目','','data-sheet="project"')}</div>${note('手机选择电脑上已有的目录。路径与读写权限确认后才绑定工作。')}`,
resources:()=>`${title('对话中的内容','回到来源，或者继续处理。')}${section('成果',linkRow('file','周末散步清单','library-detail','文档 · 最新版本')+row('history','查看旧版本','昨天 20:15','data-go="library-detail"'))}${section('来源',linkRow('chat','昨天的周末安排','history','打开原对话位置')+(S.forgotten?note('对应记忆已遗忘。'):row('bookmark','周末喜欢留出空白','只在主动查看来源时展示','data-memory="preference"')))}${section('过程',linkRow('terminal','整理清单','task','2 个步骤 · 已完成'))}`,
task:()=>`${title('整理清单','示例电脑 · 工作模式')}<span class="chip">${icon('allow')}已完成</span><div style="margin-top:var(--s-24)"><div class="timeline-entry"><h3>读取已有的安排</h3><p>查看周末计划中的文字内容。</p></div><div class="timeline-entry"><h3>生成清单</h3><p>把时间点和出门用品整理成文档。</p><pre class="text-output">读取：周末安排.txt\n生成：散步清单.txt\n结果：已完成（合成示例）</pre></div></div>${button('查看成果','data-go="library-detail"','full primary')}${button('回到来源对话','data-tab="chat"','full outline')}${button('查看待批准示例','data-sheet="approval"','full')}`,
goals:()=>`${title('目标与提醒','把想做的事，慢慢做下去。')}${offlineNote()}<div class="group">${linkRow('bell','手机提醒','reminders','明天 09:00 · 带水出门','2')}${linkRow('clock','定时任务','schedules','每周日 · 整理本周回顾','1')}</div><h3 class="section-title">进行中的目标</h3>${S.goalState==='active'?`<button class="goal-block" data-go="goal-detail"><span class="chip">${S.goalPaused?'已暂停':'进行中'}</span><h3>每周留一个上午给自己</h3><p>这个月完成了 3 次，还剩 2 次。</p><div class="progress-track"><span></span></div><div class="row-between caption"><span>3 / 5 次</span><span>下次：这周六</span></div></button>`:note(S.goalState==='complete'?'「每周留一个上午给自己」已完成。':'这个目标已移出，来源对话保留。')}<button class="goal-block" data-go="task"><span class="chip">正在处理</span><h3>整理书房清单</h3><p>等你批准后继续。</p></button><h3 class="section-title">已经完成</h3>${row('allow','整理十月阅读笔记','昨天完成','data-go="library-detail"')}${button('聊聊一个新目标','data-fill="我想开始一个新目标"','full outline')}`,
'goal-detail':()=>`${title('每周留一个上午给自己','长期目标 · 从 10 月 6 日开始')}<span class="chip">${S.goalPaused?'已暂停':'进行中'}</span><div class="progress-track"><span></span></div><div class="row-between caption"><span>已完成 3 次</span><span>计划 5 次</span></div><h3 class="section-title">下一步</h3><p>这周六去公园散步，不把时间排满。</p>${section('最近的进展',linkRow('allow','第三次：在家读书','history','10 月 24 日')+linkRow('allow','第二次：沿河散步','history','10 月 17 日')+linkRow('allow','第一次：去公园走走','history','10 月 10 日'))}${button('打开来源对话','data-tab="chat"','full primary')}${button('管理目标','data-sheet="goal-actions"','full outline')}`,
reminders:()=>`${title('手机提醒','电脑不在线，也能准时提醒。')}<div class="notice">通知已开启（示例）${button('通知权限','data-sheet="notifications"')}</div><div class="group reminder-list">${S.reminders.map(r=>`<div class="list-row"><span class="row-copy"><strong>${escapeHTML(r.text)}</strong><small>${r.complete?'已完成':escapeHTML(r.date.replace('T',' '))+' · 手机提醒'}</small></span>${ib('more','提醒操作',`data-reminder="${r.id}"`)}</div>`).join('')}</div>${button('新建提醒','data-action="reminder-new"','full primary')}`,

schedules:()=>S.scheduleDeleted?`${title('定时任务')}<div class="empty">${icon('clock')}<h3>没有待运行的定时任务</h3><p>已删除的示例不再运行，已有结果保留。</p>${button('查看之前的执行','data-go="task"','outline')}</div>`:`${title('定时任务','电脑上的安排，集中在这里。')}${offlineNote()}<div class="group"><div class="list-row"><span class="row-copy"><strong>整理本周回顾</strong><small>每周日 20:00 · 设备时区<br>下次：11 月 1 日</small></span><button class="button outline" data-action="schedule-pause">暂停</button></div>${linkRow('history','查看最近执行','task','10 月 25 日 · 已完成')}${row('play','立即运行','','data-feedback="示例任务已排队"')}${row('trash','删除定时任务','','data-sheet="schedule-delete"')}</div>${note('新增或调整定时任务，在对话里告诉 WeftMate。')}${button('设置一个定时任务','data-fill="每周日晚上帮我整理这一周的回顾"','full outline')}`,
library:()=>`${title('成果库','做过的东西，随时找得到。')}${offlineNote()}${search('搜索文件名','library')}${segment(['全部','文档','表格','图片','代码'],'成果类型')}<h3 class="section-title">今天</h3><div data-file-type="文档">${linkRow('file','周末散步清单','library-detail','文档 · 来自周末的散步计划')}</div><div data-file-type="表格">${linkRow('grid','十月阅读记录','library-detail','表格 · 12 条记录')}</div><h3 class="section-title">昨天</h3><div data-file-type="图片">${linkRow('image','书房收纳布局','library-detail','图片 · 整理书房清单')}</div><div data-file-type="代码">${linkRow('code','清单整理脚本','library-detail','代码 · 示例电脑')}</div>${note('各类型在此展示相同的预览入口；实际文件由原生预览器显示。')}`,
'library-detail':()=>`${title(S.fileType==='文档'?'周末散步清单':S.fileType==='表格'?'十月阅读记录':S.fileType==='图片'?'书房收纳布局':'清单整理脚本',S.fileType+' · 合成成果预览')}<div class="file-preview">${S.fileType==='文档'?'<h3>一个不赶时间的上午</h3>':S.fileType==='表格'?'<h3>十月阅读记录</h3><p>书名 / 页数 / 日期</p>':S.fileType==='图片'?'<h3>书房收纳布局</h3><p>图片预览区域 · 原生版显示实际图片</p>':'<h3>清单整理脚本</h3><pre class="text-output">items.sort(byPriority)</pre>'}<p>09:30 左右，带水出发。</p><p>沿湖走一圈，喜欢哪里就多待一会儿。</p><p>11:00 前后，自由返程。</p><hr style="border:0;border-top:1px solid var(--line);margin:var(--s-20) 0"><small>随身：水、钥匙、舒服的鞋。</small></div><div class="row-between">${button(icon('download')+'保存文件','data-action="download"','primary')}${button(icon('share')+'分享','data-sheet="file-actions"','outline')}</div>${section('这份成果',linkRow('chat','打开来源对话','chat','周末的散步计划')+row('history','旧版本','昨天 20:15','data-sheet="versions"'))}`,
memory:()=>`${title('记忆','看看它如何理解你。')}${offlineNote()}<div class="notice">${S.state==='offline'?'正在查看电脑同步来的只读副本。':'记忆由电脑整理，手机查看同步副本。'}<br><span class="caption">上次同步 08:45 · 原话收到与记忆形成分开显示</span></div>${search('搜索记忆','memory')}${segment(['全部','偏好','事实','待核对'],'记忆类别')}${S.forgottenIDs.has('preference')?'':`<button class="memory-item" data-kind="偏好" data-memory="preference"><p>周末喜欢留出不赶时间的空白。</p><small>偏好 · 来自 2 段对话</small></button>`}${S.forgottenIDs.has('fact')?'':`<button class="memory-item" data-kind="事实" data-memory="fact"><p>最近在读一本关于城市散步的书。</p><small>事实 · 昨天更新</small></button>`}${S.forgottenIDs.has('review')?'':`<button class="memory-item" data-kind="待核对" data-memory="review"><p>周六早晨是否方便安排活动？</p><small>待核对 · 有新的说法</small></button>`}${section('同步与清理',row('sync','原话交接状态','','data-sheet="sync"')+linkRow('trash','查看遗忘进度','memory-cleanup'))}`,
'memory-detail':()=>S.forgottenIDs.has(S.memoryID)?`${title('这条内容已遗忘')}<p class="note">记忆和所列来源已经清理。其他无关的记忆仍然可以查看。</p>${button('查看清理回执','data-go="memory-cleanup"','full outline')}`:`${title(S.memoryKind==='事实'?'最近在读的书':S.memoryKind==='待核对'?'周六早晨的安排':'周末喜欢留白',S.memoryKind+' · 来自电脑记忆')}${S.mutedIDs.has(S.memoryID)?'<span class="chip">已停用 · 不用于回答</span>':''}<p>${S.memoryKind==='事实'?'最近在读一本关于城市散步的书。':S.memoryKind==='待核对'?'周六早晨是否方便安排活动？有新的说法，等你核对。':'你喜欢给周末留出不用赶路、不必完成目标的一段时间。'}</p>${section('为什么会这样理解',memorySources())}${S.state==='offline'?`<div class="notice" style="margin-top:var(--s-24)">这是只读副本。纠正、停用和遗忘需要连接电脑后确认范围。</div>${button('查看连接','data-go="devices"','full outline')}`:`${button('不准确，纠正它','data-sheet="correct-memory"','full primary')}${button('更多操作','data-sheet="memory-actions"','full outline')}`}${note('遗忘前列出受影响的记忆、来源和副本；没有读到范围时不提供确认按钮。')}`,
'memory-cleanup':()=>`${title('遗忘进度','每一处清理都有可见的状态。')}<div class="group">${row('allow','电脑记忆','已删除示例记忆与来源','data-feedback="电脑删除已确认（示例）"')}${row('allow','此手机副本','已清理','data-feedback="此手机清理已确认（示例）"')}${row('sync','另一台设备','等待上线清理','data-sheet="cleanup-retry"')}</div>${note('还有设备没有回执时，只显示等待，不提前写「全部完成」。')}${button('重新确认清理状态','data-feedback="另一台设备仍未上线，继续保留待清理状态"','full outline')}`,
settings:()=>`${title('设置')}<div class="group">${linkRow('account','示例账号','account','个人空间','账号与安全')}</div>${search('搜索设置','settings')}${section('你的手机',linkRow('settings','常规','general','回复与回顾')+linkRow('palette','外观','appearance','跟随系统')+linkRow('health','健康数据','health-settings','读取与使用范围')+linkRow('desktop','设备','devices','1 台电脑已配对'))}${section('助手',linkRow('model','模型服务','models')+linkRow('approval','审批','approvals')+linkRow('chart','用量','usage')+linkRow('bookmark','记忆','memory')+linkRow('clock','提醒与定时任务','schedules'))}${section('对话与维护',linkRow('phone','手机上的对话','conversations')+linkRow('archive','已归档','archived')+linkRow('tool','系统状态','system')+linkRow('info','关于','about'))}<p class="search-empty note" hidden>没有找到这个设置。</p>${button('退出登录','data-action="logout"','full outline danger')}`,
general:()=>`${title('常规')}${section('回复',row('queue','回复中发送的消息','按账户保存在这台设备','data-sheet="running-mode"','排队'))}${section('回顾与洞察',toggle('每周回顾','把这一周的事情放到动态里',true))}${section('连接',linkRow('desktop','电脑连接','devices','配对、重新连接与切换'))}${note('操作尚未收到回执时，保留原提交并显示核对入口，不重复创建请求。')}`,
appearance:()=>`${title('外观','熟悉的布局，适合眼前的光线。')}${segment(['跟随系统','浅色','深色'],'外观',S.theme==='dark'?2:1)}<div class="group">${row('palette','主题色','与电脑端一致的石墨色','data-feedback="设计稿采用石墨色，主题扩展沿用共享令牌"','石墨')}${row('type','字号','随系统文字大小调整','data-action="large-type"','预览大字号')}${toggle('减少动态效果','省去位移，保留状态变化',reduceMotion(),'reduce-motion')}</div>${note('原生版直接跟随系统的文字大小、减少动态效果与减少透明度设置。页面和输入草稿在换色时保持。')}`,
account:()=>`${title('账号与安全')}<div class="group">${row('account','示例账号','hello@example.com','data-feedback="这是合成账号，不连接真实账户"')}${linkRow('mail','换绑邮箱','change-email')}${linkRow('key','修改密码','change-password')}${linkRow('desktop','登录设备','devices')}</div>${section('会话与账号',row('logout','退出所有其他设备','保留当前手机登录','data-sheet="other-devices"')+row('trash','注销账号','需要重新验证并确认影响','data-sheet="delete-account"'))}${button('退出当前账号','data-action="logout"','full outline danger')}`,
'change-email':()=>`${title('换绑邮箱','验证新邮箱后，账号内容继续保留。')}${field('新邮箱','name@example.com','','email')}${button('发送新邮箱验证码','data-feedback="示例验证码已发送；原型不发送邮件"','full outline')}${field('新邮箱验证码','6 位数字','','text')}${button('确认换绑邮箱','data-action="save-form"','full primary')}`,
'change-password':()=>`${title('修改密码')}${field('当前密码','','','password')}${field('新密码','至少 8 位','','password')}${field('确认新密码','','','password')}${button('保存新密码','data-action="save-form"','full primary')}${note('这里只演示表单，不记录输入的密码；请使用合成内容。')}`,
devices:()=>`${title('设备','聊天在手机，电脑负责把事情做下去。')}<div class="group">${row('desktop','示例电脑',S.state==='offline'?'暂时离线 · 上次连接 08:45':'已连接 · 原话可交给电脑','data-sheet="computer"')}${row('phone','这台 iPhone','当前设备 · 最近使用 刚刚','data-sheet="device-actions"')}${row('desktop','示例平板','上次使用 昨天','data-sheet="device-actions"')}</div>${button('添加电脑','data-go="pairing"','full primary')}${section('连接状态',row('sync','重新连接电脑','','data-feedback="已重新连接示例电脑"')+row('edit','电脑改名','','data-sheet="rename-device"'))}${note('切换电脑时保留对话归属；新电脑没有原模型时，先询问再继续。')}`,
models:()=>`${title('模型服务','每段对话都能选自己的模型。')}<div class="group">${S.serviceDeleted?note('示例服务已移除，可以添加新服务。'):linkRow('cloud','账户云模型','model-edit','已配置 · 2 个模型')}${linkRow('desktop','示例本地服务','model-edit','电脑在线时可用')}${linkRow('plus','添加模型服务','model-edit')}</div>${section('默认选择',row('model','主模型','创建对话时选择，已有对话保留原模型','data-sheet="models"','账户云模型')+row('model','后台模型','用于标题和记忆整理','data-sheet="models"','账户云模型'))}${section('模型档案',row('chart','单价与能力','每百万字输入、输出单价；图片与深入思考能力','data-sheet="model-profile"'))}`,
'model-edit':()=>`${title('编辑模型服务','连接信息只留在自己的配置里。')}${field('服务名称','给它一个容易认的名字','示例服务')}${field('服务地址','https://api.example.com/v1','https://api.example.com/v1','url')}${field('API 密钥','输入示例密钥','','password')}<div class="row-between">${button('读取模型','data-action="show-error"','outline')}${button('保存','data-action="save-form"','primary')}</div><div class="form-feedback"></div>${section('已读取的模型',row('model','示例对话模型','支持图片 · 支持深入思考','data-sheet="model-profile"')+row('model','示例轻量模型','文字对话','data-sheet="model-profile"'))}${button('删除这个服务','data-sheet="delete-service"','full outline danger')}`,
usage:()=>`${title('用量','本月 · 合成示例')}${segment(['本月','上月'],'用量月份')}<div class="metric-number">¥ 12.80</div>${note('按模型配置的单价估算；没有价格的部分单列，不当作零。')}<div class="measure-grid"><p>已统计请求<strong>146 次</strong></p><p>未配置单价<strong>3 次</strong></p></div>${section('按模型',row('cloud','账户云模型','128 次请求','data-feedback="账户云模型 · 输入输出用量示例"','¥ 11.20')+row('model','示例轻量模型','18 次请求','data-feedback="示例轻量模型 · 输入输出用量示例"','¥ 1.60'))}${section('提醒',row('chart','月度费用上限','接近上限时提醒','data-sheet="budget"','¥ 50'))}`,
approvals:()=>`${title('审批','只影响新建的工作对话。')}${section('默认审批模式',row('approval','自动（推荐）','需要你确认的操作会单独提出','data-sheet="approval-mode"'))}${section('额外核对',toggle('动手前多看一眼','让另一个模型复核操作计划',true))}${note('已有对话在输入框里调整。手机自己聊天不执行电脑操作，无需审批。')}${button('看一次待批准的样子','data-sheet="approval"','full outline')}`,
archived:()=>`${title('已归档','恢复后继续接着聊。')}<div class="group"><div class="list-row"><span class="row-copy"><strong>九月的阅读计划</strong><small>9 月 30 日归档</small></span>${button('恢复','data-action="restore"','outline')}${ib('trash','删除归档对话','data-sheet="delete-conversation"')}</div></div>${note('归档只从日常列表收起。删除与遗忘分开确认。')}`,
system:()=>`${title('系统状态','示例电脑 · 上次检查 09:40')}<div class="group">${row('desktop','电脑连接','已连接','data-feedback="连接状态来自示例"','正常')}${row('model','后台模型','账户云模型','data-go="models"','可用')}${row('bookmark','记忆服务','已就绪','data-go="memory"','正常')}${row('sync','原话交接','2 条电脑已收到','data-sheet="sync"','已接收')}</div>${button('刷新状态','data-feedback="示例状态已刷新"','full outline')}${note('手机只查看电脑状态。重启修复与备份恢复在电脑端处理。')}`,
about:()=>`${title('关于 WeftMate','你的对话、记忆与日常事情。')}<img class="auth-brand" src="../../icons/app/monochrome.svg" alt="WeftMate"><div class="group">${row('info','版本','本页为设计原型','data-feedback="产品实际版本由原生程序读取"','设计预览')}${row('download','检查更新','通过 TestFlight / App Store 更新','data-feedback="原型不打开分发服务"')}${linkRow('file','隐私与条款','legal')}${linkRow('list','运行记录','diagnostics')}</div>${note('此原型中的账号、对话、健康与文件都是合成示例。')}`,
diagnostics:()=>`${title('运行记录','只在排查问题时打开。')}<div class="group">${toggle('记录运行信息','随时关闭，可删除已有记录',false)}${row('list','最近记录','09:40 启动 · 09:41 读取示例页面','data-sheet="run-log"')}${row('share','导出诊断信息','导出前预览，检查敏感内容','data-sheet="run-log"')}${row('trash','清空记录','','data-sheet="clear-log"')}</div>${note('诊断标识、内部状态和接口错误不进入普通聊天文案。')}`,
legal:()=>`${title('隐私与条款','文档入口与阅读排版预览')}<div class="legal-text"><p>这里承载产品现有的隐私政策和服务条款全文。实施时直接读取 AuthView.swift 中 LegalDocument 的正式内容。</p><p>本页只展示长文阅读、返回和字号行为，不编写新的法律条款。</p><h3>在手机上阅读</h3><p>正文保持可选择、可复制，连续滚动。返回时恢复之前的页面和位置。</p></div>${button('返回','data-action="back"','full outline')}`,
login:()=>`<div class="auth"><img class="auth-brand" src="../../icons/app/monochrome.svg" alt="WeftMate"><h2>把日常，接着聊下去。</h2><p>登录你的账号。手机自己就能聊天，电脑可以稍后再添加。</p>${segment(['验证码','密码'],'登录方式')}${field('邮箱','name@example.com','','email')}<div class="password-login" hidden>${field('密码','','','password')}</div>${button('继续','data-action="login-code"','full primary')}<div class="row-between" style="margin-top:var(--s-16)"><button class="inline-link" data-go="register">创建账号</button><button class="inline-link" data-go="recovery">忘记密码</button></div>${button('先看看手机对话','data-tab="chat"','full')}${note('这是原型，不连接真实账号。请勿输入真实密码。')}${button('服务条款与隐私政策','data-go="legal"','full')}</div>`,
register:()=>`<div class="auth">${title('创建账号','用邮箱把自己的设备连起来。')}${field('邮箱','name@example.com','','email')}${field('密码','至少 8 位','','password')}${field('确认密码','','','password')}${button('发送验证码','data-action="login-code"','full primary')}${note('正式注册沿用现有密码强度检查、验证码冷却与条款确认。')}${button('阅读服务条款与隐私政策','data-go="legal"','full')}${button('已有账号，去登录','data-go="login"','full outline')}</div>`,
recovery:()=>`${title('找回密码','验证邮箱后再设置新密码。')}${field('邮箱','name@example.com','','email')}${button('发送验证码','data-action="login-code"','full primary')}${button('回到登录','data-go="login"','full outline')}`,
verify:()=>`${title('看一下你的邮箱','输入收到的 6 位验证码。')}${field('验证码','原型可填任意 6 位数字','','text')}${button('验证并继续','data-action="verify"','full primary')}${button('重新发送验证码','data-action="resend-code"','full outline')}${note('真实流程区分登录验证、注册验证和找回密码。验证码错误、过期或限流时原位说明，并保留邮箱。')}`,
pairing:()=>`${title('添加你的电脑','打开电脑上的 WeftMate，扫描配对码。')}<div class="scanner">${icon('camera')}<p>相机取景位置</p>${button('模拟扫到配对码','data-action="pair-scan"','outline')}</div>${button('手动输入地址与配对码','data-sheet="pair-manual"','full outline')}${button('稍后添加，先聊天','data-tab="chat"','full')}${note('真机请求相机权限。拒绝授权时保留手动输入；不会自动登录或添加未知电脑。')}`,
'pair-confirm':()=>`${title('确认是你的电脑','请核对两边显示的数字一致。')}<div class="group">${row('desktop','示例电脑','正在等待你确认','data-feedback="这是合成配对对象"')}</div><div class="code">482 916</div>${note('两边一致再确认。不认识这台电脑，取消即可。')}${button('一致，完成配对','data-action="pair-confirm"','full primary')}${button('不是这台电脑','data-go="pairing"','full outline')}`
};
